class Student extends DataClass implements Insertable<Student> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String deviceId;

  /// Generated from the centre's own pattern, e.g. `AEC-26-00427`.
  final String code;

  /// The name used everywhere in the interface. May itself be Bangla — this is
  /// content, not chrome.
  final String name;

  /// Optional second-script name, for centres that keep both.
  final String nameAlt;
  final String? photoPath;
  final DateTime? dateOfBirth;
  final Gender? gender;

  /// The school or college the student attends outside the centre.
  final String school;
  final String studentPhone;
  final String studentPhoneNorm;
  final String guardianName;
  final String guardianRelation;
  final String guardianPhone;
  final String guardianPhoneNorm;
  final String address;
  final String bloodGroup;
  final DateTime admissionDate;
  final StudentStatus status;

  /// What this student pays each month, in whole Taka.
  ///
  /// Held per student rather than read from the batch: a batch fee is a
  /// starting point, but siblings, scholarships and negotiated rates mean the
  /// real figure differs person to person, and billing should use the real one.
  final int monthlyFee;

  /// How they heard about the centre, for the owner's own marketing sense.
  final String referredBy;
  final String notes;
  const Student({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.deviceId,
    required this.code,
    required this.name,
    required this.nameAlt,
    this.photoPath,
    this.dateOfBirth,
    this.gender,
    required this.school,
    required this.studentPhone,
    required this.studentPhoneNorm,
    required this.guardianName,
    required this.guardianRelation,
    required this.guardianPhone,
    required this.guardianPhoneNorm,
    required this.address,
    required this.bloodGroup,
    required this.admissionDate,
    required this.status,
    required this.monthlyFee,
    required this.referredBy,
    required this.notes,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['device_id'] = Variable<String>(deviceId);
    map['code'] = Variable<String>(code);
    map['name'] = Variable<String>(name);
    map['name_alt'] = Variable<String>(nameAlt);
    if (!nullToAbsent || photoPath != null) {
      map['photo_path'] = Variable<String>(photoPath);
    }
    if (!nullToAbsent || dateOfBirth != null) {
      map['date_of_birth'] = Variable<DateTime>(dateOfBirth);
    }
    if (!nullToAbsent || gender != null) {
      map['gender'] = Variable<String>(
        $StudentsTable.$convertergendern.toSql(gender),
      );
    }
    map['school'] = Variable<String>(school);
    map['student_phone'] = Variable<String>(studentPhone);
    map['student_phone_norm'] = Variable<String>(studentPhoneNorm);
    map['guardian_name'] = Variable<String>(guardianName);
    map['guardian_relation'] = Variable<String>(guardianRelation);
    map['guardian_phone'] = Variable<String>(guardianPhone);
    map['guardian_phone_norm'] = Variable<String>(guardianPhoneNorm);
    map['address'] = Variable<String>(address);
    map['blood_group'] = Variable<String>(bloodGroup);
    map['admission_date'] = Variable<DateTime>(admissionDate);
    {
      map['status'] = Variable<String>(
        $StudentsTable.$converterstatus.toSql(status),
      );
    }
    map['monthly_fee'] = Variable<int>(monthlyFee);
    map['referred_by'] = Variable<String>(referredBy);
    map['notes'] = Variable<String>(notes);
    return map;
  }

  StudentsCompanion toCompanion(bool nullToAbsent) {
    return StudentsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      deviceId: Value(deviceId),
      code: Value(code),
      name: Value(name),
      nameAlt: Value(nameAlt),
      photoPath: photoPath == null && nullToAbsent
          ? const Value.absent()
          : Value(photoPath),
      dateOfBirth: dateOfBirth == null && nullToAbsent
          ? const Value.absent()
          : Value(dateOfBirth),
      gender: gender == null && nullToAbsent
          ? const Value.absent()
          : Value(gender),
      school: Value(school),
      studentPhone: Value(studentPhone),
      studentPhoneNorm: Value(studentPhoneNorm),
      guardianName: Value(guardianName),
      guardianRelation: Value(guardianRelation),
      guardianPhone: Value(guardianPhone),
      guardianPhoneNorm: Value(guardianPhoneNorm),
      address: Value(address),
      bloodGroup: Value(bloodGroup),
      admissionDate: Value(admissionDate),
      status: Value(status),
      monthlyFee: Value(monthlyFee),
      referredBy: Value(referredBy),
      notes: Value(notes),
    );
  }

