      school: serializer.fromJson<String>(json['school']),
      studentPhone: serializer.fromJson<String>(json['studentPhone']),
      studentPhoneNorm: serializer.fromJson<String>(json['studentPhoneNorm']),
      guardianName: serializer.fromJson<String>(json['guardianName']),
      guardianRelation: serializer.fromJson<String>(json['guardianRelation']),
      guardianPhone: serializer.fromJson<String>(json['guardianPhone']),
      guardianPhoneNorm: serializer.fromJson<String>(json['guardianPhoneNorm']),
      address: serializer.fromJson<String>(json['address']),
      bloodGroup: serializer.fromJson<String>(json['bloodGroup']),
      admissionDate: serializer.fromJson<DateTime>(json['admissionDate']),
      status: $StudentsTable.$converterstatus.fromJson(
