class Invoice extends DataClass implements Insertable<Invoice> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String deviceId;
  final String studentId;
  final String sessionId;
  final String? batchId;

  /// `2026-03` for a monthly invoice; free text for one-offs. Used to stop the
  /// same month being billed twice.
  final String periodKey;
  final DateTime issuedOn;
  final DateTime? dueOn;
  final int grossAmount;
  final int discountAmount;

  /// gross - discount. Stored rather than computed so a historical invoice
  /// cannot change when a discount is edited later.
  final int netAmount;
  final int paidAmount;
  final InvoiceStatus status;
  final String note;
  const Invoice({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.deviceId,
    required this.studentId,
    required this.sessionId,
    this.batchId,
    required this.periodKey,
    required this.issuedOn,
    this.dueOn,
    required this.grossAmount,
    required this.discountAmount,
    required this.netAmount,
    required this.paidAmount,
    required this.status,
    required this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['device_id'] = Variable<String>(deviceId);
    map['student_id'] = Variable<String>(studentId);
    map['session_id'] = Variable<String>(sessionId);
    if (!nullToAbsent || batchId != null) {
      map['batch_id'] = Variable<String>(batchId);
    }
    map['period_key'] = Variable<String>(periodKey);
    map['issued_on'] = Variable<DateTime>(issuedOn);
    if (!nullToAbsent || dueOn != null) {
      map['due_on'] = Variable<DateTime>(dueOn);
    }
    map['gross_amount'] = Variable<int>(grossAmount);
    map['discount_amount'] = Variable<int>(discountAmount);
    map['net_amount'] = Variable<int>(netAmount);
    map['paid_amount'] = Variable<int>(paidAmount);
    {
      map['status'] = Variable<String>(
        $InvoicesTable.$converterstatus.toSql(status),
      );
    }
    map['note'] = Variable<String>(note);
    return map;
  }

  InvoicesCompanion toCompanion(bool nullToAbsent) {
    return InvoicesCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      deviceId: Value(deviceId),
      studentId: Value(studentId),
      sessionId: Value(sessionId),
      batchId: batchId == null && nullToAbsent
          ? const Value.absent()
          : Value(batchId),
      periodKey: Value(periodKey),
      issuedOn: Value(issuedOn),
      dueOn: dueOn == null && nullToAbsent
          ? const Value.absent()
          : Value(dueOn),
      grossAmount: Value(grossAmount),
      discountAmount: Value(discountAmount),
      netAmount: Value(netAmount),
      paidAmount: Value(paidAmount),
      status: Value(status),
      note: Value(note),
    );
  }

  factory Invoice.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Invoice(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      deviceId: serializer.fromJson<String>(json['deviceId']),
      studentId: serializer.fromJson<String>(json['studentId']),
      sessionId: serializer.fromJson<String>(json['sessionId']),
      batchId: serializer.fromJson<String?>(json['batchId']),
      periodKey: serializer.fromJson<String>(json['periodKey']),
      issuedOn: serializer.fromJson<DateTime>(json['issuedOn']),
      dueOn: serializer.fromJson<DateTime?>(json['dueOn']),
      grossAmount: serializer.fromJson<int>(json['grossAmount']),
      discountAmount: serializer.fromJson<int>(json['discountAmount']),
      netAmount: serializer.fromJson<int>(json['netAmount']),
      paidAmount: serializer.fromJson<int>(json['paidAmount']),
      status: $InvoicesTable.$converterstatus.fromJson(
        serializer.fromJson<String>(json['status']),
      ),
      note: serializer.fromJson<String>(json['note']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deletedAt': serializer.toJson<DateTime?>(deletedAt),
      'deviceId': serializer.toJson<String>(deviceId),
      'studentId': serializer.toJson<String>(studentId),
      'sessionId': serializer.toJson<String>(sessionId),
      'batchId': serializer.toJson<String?>(batchId),
      'periodKey': serializer.toJson<String>(periodKey),
      'issuedOn': serializer.toJson<DateTime>(issuedOn),
      'dueOn': serializer.toJson<DateTime?>(dueOn),
      'grossAmount': serializer.toJson<int>(grossAmount),
      'discountAmount': serializer.toJson<int>(discountAmount),
      'netAmount': serializer.toJson<int>(netAmount),
      'paidAmount': serializer.toJson<int>(paidAmount),
      'status': serializer.toJson<String>(
        $InvoicesTable.$converterstatus.toJson(status),
      ),
      'note': serializer.toJson<String>(note),
    };
  }

  Invoice copyWith({
    String? id,
    DateTime? createdAt,
    DateTime? updatedAt,
    Value<DateTime?> deletedAt = const Value.absent(),
    String? deviceId,
    String? studentId,
    String? sessionId,
    Value<String?> batchId = const Value.absent(),
    String? periodKey,
    DateTime? issuedOn,
    Value<DateTime?> dueOn = const Value.absent(),
    int? grossAmount,
    int? discountAmount,
    int? netAmount,
    int? paidAmount,
    InvoiceStatus? status,
    String? note,
  }) => Invoice(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    deletedAt: deletedAt.present ? deletedAt.value : this.deletedAt,
    deviceId: deviceId ?? this.deviceId,
    studentId: studentId ?? this.studentId,
    sessionId: sessionId ?? this.sessionId,
    batchId: batchId.present ? batchId.value : this.batchId,
    periodKey: periodKey ?? this.periodKey,
    issuedOn: issuedOn ?? this.issuedOn,
    dueOn: dueOn.present ? dueOn.value : this.dueOn,
    grossAmount: grossAmount ?? this.grossAmount,
    discountAmount: discountAmount ?? this.discountAmount,
    netAmount: netAmount ?? this.netAmount,
    paidAmount: paidAmount ?? this.paidAmount,
    status: status ?? this.status,
    note: note ?? this.note,
  );
  Invoice copyWithCompanion(InvoicesCompanion data) {
    return Invoice(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      deletedAt: data.deletedAt.present ? data.deletedAt.value : this.deletedAt,
      deviceId: data.deviceId.present ? data.deviceId.value : this.deviceId,
      studentId: data.studentId.present ? data.studentId.value : this.studentId,
      sessionId: data.sessionId.present ? data.sessionId.value : this.sessionId,
      batchId: data.batchId.present ? data.batchId.value : this.batchId,
      periodKey: data.periodKey.present ? data.periodKey.value : this.periodKey,
      issuedOn: data.issuedOn.present ? data.issuedOn.value : this.issuedOn,
      dueOn: data.dueOn.present ? data.dueOn.value : this.dueOn,
      grossAmount: data.grossAmount.present
          ? data.grossAmount.value
          : this.grossAmount,
      discountAmount: data.discountAmount.present
          ? data.discountAmount.value
          : this.discountAmount,
      netAmount: data.netAmount.present ? data.netAmount.value : this.netAmount,
      paidAmount: data.paidAmount.present
          ? data.paidAmount.value
          : this.paidAmount,
      status: data.status.present ? data.status.value : this.status,
      note: data.note.present ? data.note.value : this.note,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Invoice(')
          ..write('id: $id, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deletedAt: $deletedAt, ')
          ..write('deviceId: $deviceId, ')
          ..write('studentId: $studentId, ')
          ..write('sessionId: $sessionId, ')
          ..write('batchId: $batchId, ')
          ..write('periodKey: $periodKey, ')
          ..write('issuedOn: $issuedOn, ')
          ..write('dueOn: $dueOn, ')
          ..write('grossAmount: $grossAmount, ')
          ..write('discountAmount: $discountAmount, ')
          ..write('netAmount: $netAmount, ')
          ..write('paidAmount: $paidAmount, ')
          ..write('status: $status, ')
          ..write('note: $note')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    createdAt,
    updatedAt,
