class InvoiceItem extends DataClass implements Insertable<InvoiceItem> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String deviceId;
  final String invoiceId;
  final String feeHeadId;
  final String label;
  final int amount;
  final int discount;
  const InvoiceItem({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.deviceId,
    required this.invoiceId,
    required this.feeHeadId,
    required this.label,
    required this.amount,
    required this.discount,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['device_id'] = Variable<String>(deviceId);
    map['invoice_id'] = Variable<String>(invoiceId);
    map['fee_head_id'] = Variable<String>(feeHeadId);
    map['label'] = Variable<String>(label);
    map['amount'] = Variable<int>(amount);
    map['discount'] = Variable<int>(discount);
    return map;
  }

  InvoiceItemsCompanion toCompanion(bool nullToAbsent) {
    return InvoiceItemsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      deviceId: Value(deviceId),
      invoiceId: Value(invoiceId),
      feeHeadId: Value(feeHeadId),
      label: Value(label),
      amount: Value(amount),
      discount: Value(discount),
    );
  }

  factory InvoiceItem.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return InvoiceItem(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      deviceId: serializer.fromJson<String>(json['deviceId']),
      invoiceId: serializer.fromJson<String>(json['invoiceId']),
      feeHeadId: serializer.fromJson<String>(json['feeHeadId']),
      label: serializer.fromJson<String>(json['label']),
      amount: serializer.fromJson<int>(json['amount']),
      discount: serializer.fromJson<int>(json['discount']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deletedAt': serializer.toJson<DateTime?>(deletedAt),
      'deviceId': serializer.toJson<String>(deviceId),
      'invoiceId': serializer.toJson<String>(invoiceId),
      'feeHeadId': serializer.toJson<String>(feeHeadId),
      'label': serializer.toJson<String>(label),
      'amount': serializer.toJson<int>(amount),
      'discount': serializer.toJson<int>(discount),
    };
  }

  InvoiceItem copyWith({
    String? id,
    DateTime? createdAt,
    DateTime? updatedAt,
    Value<DateTime?> deletedAt = const Value.absent(),
    String? deviceId,
    String? invoiceId,
    String? feeHeadId,
    String? label,
    int? amount,
    int? discount,
  }) => InvoiceItem(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    deletedAt: deletedAt.present ? deletedAt.value : this.deletedAt,
    deviceId: deviceId ?? this.deviceId,
    invoiceId: invoiceId ?? this.invoiceId,
    feeHeadId: feeHeadId ?? this.feeHeadId,
    label: label ?? this.label,
    amount: amount ?? this.amount,
    discount: discount ?? this.discount,
  );
  InvoiceItem copyWithCompanion(InvoiceItemsCompanion data) {
    return InvoiceItem(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      deletedAt: data.deletedAt.present ? data.deletedAt.value : this.deletedAt,
      deviceId: data.deviceId.present ? data.deviceId.value : this.deviceId,
      invoiceId: data.invoiceId.present ? data.invoiceId.value : this.invoiceId,
      feeHeadId: data.feeHeadId.present ? data.feeHeadId.value : this.feeHeadId,
      label: data.label.present ? data.label.value : this.label,
      amount: data.amount.present ? data.amount.value : this.amount,
      discount: data.discount.present ? data.discount.value : this.discount,
    );
  }

  @override
  String toString() {
    return (StringBuffer('InvoiceItem(')
          ..write('id: $id, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deletedAt: $deletedAt, ')
          ..write('deviceId: $deviceId, ')
          ..write('invoiceId: $invoiceId, ')
          ..write('feeHeadId: $feeHeadId, ')
          ..write('label: $label, ')
          ..write('amount: $amount, ')
          ..write('discount: $discount')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    createdAt,
    updatedAt,
    deletedAt,
    deviceId,
    invoiceId,
    feeHeadId,
    label,
    amount,
    discount,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is InvoiceItem &&
          other.id == this.id &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt &&
          other.deletedAt == this.deletedAt &&
          other.deviceId == this.deviceId &&
          other.invoiceId == this.invoiceId &&
          other.feeHeadId == this.feeHeadId &&
          other.label == this.label &&
          other.amount == this.amount &&
          other.discount == this.discount);
}

