class Question extends DataClass implements Insertable<Question> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String deviceId;
  final String subjectId;
  final String? chapterId;
  final QuestionType type;
  final Difficulty difficulty;

  /// The question itself, as HTML — the Document Engine's native format.
  final String bodyHtml;

  /// MCQ choices as a JSON array of strings.
  final String optionsJson;
  final int? correctOption;
  final String answerHtml;
  final int marks;

  /// Where it came from — "Dhaka Board 2019".
  final String sourceTag;
  final String? imagePath;

  /// So the same question does not reappear in the same batch two terms running.
  final DateTime? lastUsedAt;
  final int useCount;
  const Question({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.deviceId,
    required this.subjectId,
    this.chapterId,
    required this.type,
    required this.difficulty,
    required this.bodyHtml,
    required this.optionsJson,
    this.correctOption,
    required this.answerHtml,
    required this.marks,
    required this.sourceTag,
    this.imagePath,
    this.lastUsedAt,
    required this.useCount,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['device_id'] = Variable<String>(deviceId);
    map['subject_id'] = Variable<String>(subjectId);
    if (!nullToAbsent || chapterId != null) {
      map['chapter_id'] = Variable<String>(chapterId);
    }
    {
      map['type'] = Variable<String>(
        $QuestionsTable.$convertertype.toSql(type),
      );
    }
    {
      map['difficulty'] = Variable<String>(
        $QuestionsTable.$converterdifficulty.toSql(difficulty),
      );
    }
    map['body_html'] = Variable<String>(bodyHtml);
    map['options_json'] = Variable<String>(optionsJson);
    if (!nullToAbsent || correctOption != null) {
      map['correct_option'] = Variable<int>(correctOption);
    }
    map['answer_html'] = Variable<String>(answerHtml);
    map['marks'] = Variable<int>(marks);
    map['source_tag'] = Variable<String>(sourceTag);
    if (!nullToAbsent || imagePath != null) {
      map['image_path'] = Variable<String>(imagePath);
    }
    if (!nullToAbsent || lastUsedAt != null) {
      map['last_used_at'] = Variable<DateTime>(lastUsedAt);
    }
    map['use_count'] = Variable<int>(useCount);
    return map;
  }

  QuestionsCompanion toCompanion(bool nullToAbsent) {
    return QuestionsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      deviceId: Value(deviceId),
      subjectId: Value(subjectId),
      chapterId: chapterId == null && nullToAbsent
          ? const Value.absent()
          : Value(chapterId),
      type: Value(type),
      difficulty: Value(difficulty),
      bodyHtml: Value(bodyHtml),
      optionsJson: Value(optionsJson),
      correctOption: correctOption == null && nullToAbsent
          ? const Value.absent()
          : Value(correctOption),
      answerHtml: Value(answerHtml),
      marks: Value(marks),
      sourceTag: Value(sourceTag),
      imagePath: imagePath == null && nullToAbsent
          ? const Value.absent()
          : Value(imagePath),
      lastUsedAt: lastUsedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(lastUsedAt),
      useCount: Value(useCount),
    );
  }

  factory Question.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Question(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      deviceId: serializer.fromJson<String>(json['deviceId']),
      subjectId: serializer.fromJson<String>(json['subjectId']),
      chapterId: serializer.fromJson<String?>(json['chapterId']),
      type: $QuestionsTable.$convertertype.fromJson(
        serializer.fromJson<String>(json['type']),
      ),
      difficulty: $QuestionsTable.$converterdifficulty.fromJson(
        serializer.fromJson<String>(json['difficulty']),
      ),
      bodyHtml: serializer.fromJson<String>(json['bodyHtml']),
      optionsJson: serializer.fromJson<String>(json['optionsJson']),
      correctOption: serializer.fromJson<int?>(json['correctOption']),
      answerHtml: serializer.fromJson<String>(json['answerHtml']),
      marks: serializer.fromJson<int>(json['marks']),
      sourceTag: serializer.fromJson<String>(json['sourceTag']),
      imagePath: serializer.fromJson<String?>(json['imagePath']),
      lastUsedAt: serializer.fromJson<DateTime?>(json['lastUsedAt']),
      useCount: serializer.fromJson<int>(json['useCount']),
    );
