  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deletedAt': serializer.toJson<DateTime?>(deletedAt),
      'deviceId': serializer.toJson<String>(deviceId),
      'subjectId': serializer.toJson<String>(subjectId),
      'chapterId': serializer.toJson<String?>(chapterId),
      'type': serializer.toJson<String>(
        $QuestionsTable.$convertertype.toJson(type),
      ),
      'difficulty': serializer.toJson<String>(
        $QuestionsTable.$converterdifficulty.toJson(difficulty),
      ),
      'bodyHtml': serializer.toJson<String>(bodyHtml),
      'optionsJson': serializer.toJson<String>(optionsJson),
      'correctOption': serializer.toJson<int?>(correctOption),
      'answerHtml': serializer.toJson<String>(answerHtml),
      'marks': serializer.toJson<int>(marks),
      'sourceTag': serializer.toJson<String>(sourceTag),
      'imagePath': serializer.toJson<String?>(imagePath),
      'lastUsedAt': serializer.toJson<DateTime?>(lastUsedAt),
      'useCount': serializer.toJson<int>(useCount),
